'use strict';(()=>{const paths={grow:'grow.html',merge:'merge.html',adventure:'adventure.html',city:'city.html'},frames=new Map(),ready=new Set();let selected;function frame(id){if(frames.has(id))return frames.get(id);const f=document.createElement('iframe');f.src=paths[id];f.title={grow:'우진이 키우기',merge:'머지 우진',adventure:'우리오',city:'Grand Theft Woojin'}[id];f.id='game-'+id;f.hidden=id!==selected;f.onload=()=>{ready.add(id);f.contentWindow.postMessage({type:'game-visibility',active:id===selected},location.origin);if(id===selected)document.getElementById('loading').hidden=true};frames.set(id,f);document.body.append(f);return f}function show(id){if(!paths[id])id='grow';selected=id;frame(id);for(const[key,f]of frames){f.hidden=key!==id;f.contentWindow.postMessage({type:'game-visibility',active:key===id},location.origin)}document.querySelectorAll('[data-game]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.game===id)));document.getElementById('loading').hidden=ready.has(id);history.replaceState(null,'','#'+id)}document.querySelector('nav').onclick=e=>{const b=e.target.closest('[data-game]');if(b)show(b.dataset.game)};addEventListener('message',e=>{if(e.origin!==location.origin||![...frames.values()].some(f=>f.contentWindow===e.source))return;if(e.data?.type==='switch-game')show(e.data.game)});show(location.hash.slice(1));setTimeout(()=>Object.keys(paths).forEach(frame),300);})();
